ALTER TABLE PROJECT
ADD FOREIGN KEY (EMPLOYEE_ID)
REFERENCES EMPLOYEE (EMPLOYEE_ID);

counterexample:
/* Insert anomalous data into EMPLOYEE that violates the uniqueness constraint for demonstration purposes */
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (1, 'Alice', 10);
-- Simulate a duplicate row for Alice (as might happen in a data load error)
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (1, 'Alice Duplicate', 10);

INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (2, 'Bob', 20);

/* Now insert PROJECT rows. Note that PROJECT’s foreign key normally would prevent referencing a non‐unique EMPLOYEE record. For this test we assume a scenario (or deferred constraint checking) where the anomaly exists. */
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (100, 1);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (100, 2);

/*
Running Q1:
  SELECT A.PROJECT_ID, ROUND(AVG(B.EXPERIENCE_YEARS), 2) AS AVERAGE_YEARS
  FROM PROJECT AS A
  INNER JOIN EMPLOYEE AS B ON A.EMPLOYEE_ID = B.EMPLOYEE_ID
  GROUP BY A.PROJECT_ID;

Q1 will join using the PROJECT table’s foreign key so that for employee 1 it picks up the single valid value (or at least one copy as enforced by the constraint), yielding an average of (10 + 20)/2 = 15.00.

Running Q2:
  SELECT TMP.PROJECT_ID, ROUND(AVG(TMP.EXPERIENCE_YEARS), 2) AS AVERAGE_YEARS
  FROM (SELECT P.PROJECT_ID, P.EMPLOYEE_ID, E.EXPERIENCE_YEARS
        FROM EMPLOYEE E
        INNER JOIN PROJECT P ON E.EMPLOYEE_ID = P.EMPLOYEE_ID ) AS TMP
  GROUP BY TMP.PROJECT_ID;

Q2’s subquery starts from EMPLOYEE and finds two rows for employee 1, so the join produces three rows: two for employee 1 (each with value 10) and one for employee 2 (20). Thus the average becomes (10 + 10 + 20)/3 = 13.33, which is different from Q1's result.
*/

