INSERT INTO SALESPERSON (SALES_ID, NAME, SALARY, COMMISSION_RATE, HIRE_DATE) VALUES (2, 'Bob', 60000, 12, '2019-05-15');

INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (10, 'RED', 'New York');
INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (20, 'RED', 'Boston');
INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (30, 'BLUE', 'Chicago');

-- Bob places an order with the red company having COM_ID = 20
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (100, 20, 2, '2021-07-20', 1000);

-- (Optionally, you can insert an order for Alice with a non-red company to show she is still selected in both queries.)
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (101, 30, 1, '2021-08-15', 1500);

/* Note: This test data intentionally creates two rows for the same player and event date even though the primary key (PLAYER_ID, EVENT_DATE) would normally forbid it. In practice such a scenario can arise when the date is stored with day–level precision and a player has two separate activities on the same day. */

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 100, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 200, 3);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-02-01', 300, 4);

/*
Assume that the underlying raw log (or staging table) permits more than one activity per day per player. (In the final reporting table this would violate the PK, but here we assume the test data represents the raw log before deduplication.)
*/

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 10, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 20, 3);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-02-01', 30, 2);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-03-01', 40, 7);

/*
For player 1 both queries will consider '2020-01-01' to be the minimum date. 
– Q1 will return both rows (device 10 and 20).
– A version of Q2 written with ROW_NUMBER() would return only one row (either device 10 or 20), showing a semantic difference.
If one uses RANK() as written here, then both rows will be returned, but the fact that a different window function might be chosen in practice is what makes the two queries not logically equivalent in intent.
*/

