-- This order has a NULL SALES_ID. Although it joins with the company 'RED', its SALES_ID is NULL so that:
-- In Q1: the subquery for a specific salesperson (e.g. Alice where SALES_ID=1) does not count this order (since NULL <> 1).
-- In Q2: the subquery returns NULL, causing the NOT IN condition to evaluate to UNKNOWN and filter out Alice.
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (100, 10, NULL, '2023-01-01', 500);

