VALUES (1, 10, 1, '2022-01-01', 1, 100);

-- Insert an iPhone sale that will not join to PRODUCT (anomalous row).
-- (PRODUCT_ID 999 does not exist in PRODUCT so the inner join in Q1 will drop it, 
-- but the LEFT JOIN in Q2 will produce a row with NULLs.)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (999, 20, 1, '2022-01-02', 1, 500);

/* After these INSERTs:
   • Q1’s sub‐query (which uses an inner join) finds no iPhone sale and so returns an empty set;
     hence Buyer 1 (who bought an S8) is returned.
   • Q2’s sub‐query (with LEFT JOIN) returns one row – a row whose PRODUCT columns are NULL –
     so the sub‐query yields a NULL value; then the NOT IN predicate fails for Buyer 1,
     and Buyer 1 is not returned.
   Thus Q1 and Q2 yield different results. */

