schema:
CREATE TABLE EMPLOYEE (
    EMPID INT PRIMARY KEY,
    NAME VARCHAR,
    SUPERVISOR INT,
    SALARY INT
);

CREATE TABLE BONUS (
    EMPID INT PRIMARY KEY,
    BONUS INT,
    FOREIGN KEY (EMPID) REFERENCES EMPLOYEE (EMPID)
);

counterexample:
INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (1, 'Alice', NULL, 50000);
INSERT INTO BONUS (EMPID, BONUS) VALUES (1, NULL);

INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (2, 'Bob', NULL, 60000);
-- Note: Bob does not have a BONUS record, so after the LEFT JOIN his BONUS value is NULL

-- Running Q1:
--   SELECT EMPLOYEE.NAME, BONUS.BONUS
--   FROM EMPLOYEE LEFT JOIN BONUS ON EMPLOYEE.EMPID = BONUS.EMPID
--   WHERE BONUS < 1000 OR BONUS IS NULL;

-- Running Q2:
--   SELECT NAME, BONUS
--   FROM EMPLOYEE LEFT JOIN BONUS ON EMPLOYEE.EMPID = BONUS.EMPID
--   WHERE IFNULL(BONUS, 0) < 1000;

-- Although both queries return the two rows, the row for Alice comes from an explicit BONUS record with a NULL bonus. In Q1 the null is kept as-is, while Q2’s WHERE predicate treats that bonus as if it were 0. In a larger query or in further processing this distinction may lead to different results.

