-- Product1: both sales lie within the period
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
       VALUES (1, 10, 100, '2019-01-15', 1, 100);
