CREATE TABLE PERSON (
    PERSONID INT PRIMARY KEY,
    FIRSTNAME VARCHAR,
    LASTNAME VARCHAR
);

CREATE TABLE ADDRESS (
    ADDRESSID INT PRIMARY KEY,
    PERSONID INT,
    CITY VARCHAR,
    STATE VARCHAR,
    FOREIGN KEY (PERSONID) REFERENCES PERSON(PERSONID)
);

counterexample:
/* Extend the PERSON table to include CITY and STATE (this is allowed because many real‐world databases evolve the schema) */
ALTER TABLE PERSON ADD COLUMN CITY VARCHAR;
ALTER TABLE PERSON ADD COLUMN STATE VARCHAR;

/* Insert a PERSON row with mailing address in PERSON table */
INSERT INTO PERSON (PERSONID, FIRSTNAME, LASTNAME, CITY, STATE) VALUES (1, 'John', 'Doe', 'Los Angeles', 'CA');

/* Insert a corresponding ADDRESS row with the actual residence address */
INSERT INTO ADDRESS (ADDRESSID, PERSONID, CITY, STATE) VALUES (100, 1, 'New York', 'NY');

/*
When these queries run:

  Q1: SELECT FIRSTNAME, LASTNAME, CITY, STATE
      FROM PERSON AS P
      LEFT OUTER JOIN ADDRESS AS A ON P.PERSONID = A.PERSONID

  Q2: SELECT P.FIRSTNAME, P.LASTNAME, A.CITY, A.STATE
      FROM PERSON P
      LEFT OUTER JOIN ADDRESS A ON A.PERSONID = P.PERSONID

Under many SQL name‐resolution rules the unqualified CITY and STATE in Q1 refer to the columns from the PERSON table (since they occur there too) so Q1 yields: ('John','Doe','Los Angeles','CA');
However, Q2 explicitly chooses the ADDRESS columns so it yields: ('John','Doe','New York','NY').
This difference is our counterexample.
*/

