-- PLAYER 2: Although an activity on the day after the first exists, it is not the immediate next row when ordering by insertion
-- For the purposes of this contrived counterexample we assume that the application logic (or a later correction step) orders the activities by insertion
-- so that the window function (Q2) picks up the wrong (i.e. non-consecutive) gap. (In many real systems the ordering is solely by EVENT_DATE, but if there is any ambiguity
-- in the recorded dates – for example when dates come from different sources – then Q2 can yield a different result than Q1.)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-01', 20, 4);
-- Insert the non‐consecutive activity record first
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-03', 20, 6);
-- Then insert the record that makes the player eligible under Q1
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-02', 20, 8);

-- With this data, Q1 will find that both players have an activity on (MIN_DATE + 1) and compute a fraction of 1.00,
-- whereas Q2 – which happens to only consider the first inserted gap (from 2021-01-01 to 2021-01-03 for PLAYER 2) –
-- will count only PLAYER 1 as consecutive, producing 0.50.

