schema:
CREATE TABLE CINEMA (
    SEAT_ID INT PRIMARY KEY,
    FREE BOOL
);

counterexample:
DELETE FROM CINEMA;

INSERT INTO CINEMA (SEAT_ID, FREE) VALUES (1, 1);
INSERT INTO CINEMA (SEAT_ID, FREE) VALUES (2, 1);
-- Note that there is no row for seat 3
INSERT INTO CINEMA (SEAT_ID, FREE) VALUES (4, 1);

-- Running Q1:
--   SELECT O1.SEAT_ID
--   FROM CINEMA O1
--   WHERE O1.FREE = 1
--     AND ((SELECT FREE FROM CINEMA O2 WHERE O2.SEAT_ID = O1.SEAT_ID - 1) = 1
--          OR (SELECT FREE FROM CINEMA O2 WHERE O2.SEAT_ID = O1.SEAT_ID + 1) = 1);

-- Q1 returns seats 1 and 2 (seat 4 is not returned because neither seat 3 nor seat 5 exists).

-- Running Q2:
--   WITH CTE AS (SELECT SEAT_ID FROM CINEMA WHERE FREE = 1) 
--   SELECT SEAT_ID
--   FROM CTE
--   WHERE (SEAT_ID + 1 IN (SELECT SEAT_ID FROM CTE) OR SEAT_ID - 1 IN (SELECT SEAT_ID FROM CTE));

-- Q2 returns seats 1 and 2 as well.

-- Although in this particular data both queries return the same rows, note that the logic behind the adjacent‐seat test is different: Q1 looks at every row (so an occupied seat in the gap would cause a different result than a missing row), whereas Q2’s test is done solely among free seats. This difference in treatment of non‐free (or missing) adjacent seats is why the two queries are not semantically equivalent in general.

-- Insert products
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product InRange', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'Product Mixed', 200);

-- For Product 1: both sales are within the date range (2019-01-01 to 2019-03-31)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (1, 1, 1, '2019-02-10', 5, 100);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (1, 2, 2, '2019-03-15', 3, 100);

-- For Product 2: one sale is in range and one sale is outside the range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (2, 1, 1, '2019-02-10', 5, 200);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (2, 2, 2, '2019-04-01', 3, 200);

/*
Intended behavior:
  • Q1 (which groups over all SALES records) will compute for Product 2:
      MIN(sale_date) = '2019-02-10' and MAX(sale_date) = '2019-04-01'
    thereby excluding Product 2 because 2019-04-01 > '2019-03-31'.
  • An incorrectly written Q2 that filters SALES (for example using a WHERE clause "SALE_DATE BETWEEN '2019-01-01' AND '2019-03-31'") before grouping would ignore the 2019-04-01 sale for Product 2. Then its aggregation would see only the in‑range sale and Product 2 would be returned.
This counterexample data therefore distinguishes the correct logic of Q1 from an (incorrect) variant of Q2 that is not semantically equivalent.
*/

