-- Disable foreign key and primary key constraint checking (this is database-specific; for example, in SQLite you can do the following):
PRAGMA foreign_keys = OFF;
-- Assume that constraint enforcement is temporarily disabled so that duplicate rows can be inserted in PRODUCT.

