INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 1);

-- Note: In a standard compliant system the duplicate PRODUCT row is not allowed. However, when loading data in bulk (or when constraints are deferred) a duplicate might appear temporarily. In that case,
-- Q1 evaluates as follows:
--   For CUSTOMER 100, COUNT(DISTINCT(PRODUCT_KEY)) = 1 and the subquery in Q1 returns 1 (since the distinct value 1 appears only once in PRODUCT).
-- Q2, on the other hand, evaluates COUNT(DISTINCT(PRODUCT_KEY)) = 1 for CUSTOMER 100 but its subquery returns COUNT(*) = 2, so the condition fails and CUSTOMER 100 is not returned.

-- Re-enable the constraints (if needed for subsequent operations):
PRAGMA foreign_keys = ON;

