    EXPERIENCE_YEARS INT
);

CREATE INDEX idx_PROJECT_EMPLOYEE_ID ON PROJECT (EMPLOYEE_ID);

ALTER TABLE PROJECT
ADD FOREIGN KEY (EMPLOYEE_ID)
REFERENCES EMPLOYEE (EMPLOYEE_ID);

counterexample:
/* Simulate a schema change by adding an EXPERIENCE_YEARS column to PROJECT */
ALTER TABLE PROJECT ADD COLUMN EXPERIENCE_YEARS INT;

/* Insert data into EMPLOYEE. Note: EMPLOYEE.EXPERIENCE_YEARS are the 'real' values. */
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES
  (1, 'Alice', 10),
  (2, 'Bob', 20);

/* Insert data into PROJECT. The PROJECT table now has an extra column EXPERIENCE_YEARS.
   We purposely set this column to a different value than the one in EMPLOYEE to show the divergence.
   For project 100, although the join key is the same, the PROJECT record stores a value of 5 while
   the EMPLOYEE record stores 10 or 20. */
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID, EXPERIENCE_YEARS) VALUES
  (100, 1,  5),
  (100, 2,  5);

/* In Q1 the average will be computed as ROUND(AVG(EMPLOYEE.EXPERIENCE_YEARS),2) = ROUND((10+20)/2,2) = 15.00.
   In Q2, if the SQL engine resolves the unqualified EXPERIENCE_YEARS to PROJECT.EXPERIENCE_YEARS, then the average
   will be computed as ROUND(AVG(PROJECT.EXPERIENCE_YEARS),2) = ROUND((5+5)/2,2) = 5.00. */

-- Insert two rows for player 1 with the same EVENT_DATE (duplicate login day scenario)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 101, 2);
