CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT PRIMARY KEY,
    NAME VARCHAR,
    EXPERIENCE_YEARS INT
);

CREATE INDEX idx_PROJECT_EMPLOYEE_ID ON PROJECT (EMPLOYEE_ID);

ALTER TABLE PROJECT
ADD FOREIGN KEY (EMPLOYEE_ID)
REFERENCES EMPLOYEE (EMPLOYEE_ID);

counterexample:
-- First, alter the EMPLOYEE table to add an extra column named PROJECT_ID (this does not violate the original schema since the extra column is allowed)
ALTER TABLE EMPLOYEE ADD COLUMN PROJECT_ID INT;

-- Insert sample employees. The extra PROJECT_ID column here holds a value that is unrelated to a project’s identifier.
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS, PROJECT_ID) VALUES (1, 'Alice', 10, 1000);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS, PROJECT_ID) VALUES (2, 'Bob', 20, 2000);

-- Insert projects (using the PROJECT table's PROJECT_ID, which is a different concept)
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (101, 1);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (202, 2);

-- Explanation of expected behavior:
-- Q1:
--   SELECT A.PROJECT_ID ... FROM PROJECT A ...
--   It will return rows with PROJECT_ID 101 and 202 with averages based on the joined EMPLOYEE rows (10 and 20 years).

-- Q2:
--   SELECT PROJECT_ID ... FROM PROJECT P, EMPLOYEE E WHERE P.EMPLOYEE_ID = E.EMPLOYEE_ID GROUP BY P.PROJECT_ID
-- If the SQL engine’s name‐resolution finds the ambiguous PROJECT_ID to be the one from EMPLOYEE (because of the extra column), then Q2 might return 1000 for the first row and 2000 for the second row rather than 101 and 202. Thus the two queries yield different results.

