INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 101, 10);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 101, 7);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-01', 102, 3);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-02', 102, 8);

-- Additional comment: When run against this data,
-- Q1 will sum the day-1 events for PLAYER 1 twice (because he has 2 rows on 2020-01-02) and once for PLAYER 2,
-- so the ratio computed will be (2 + 1) / 2 = 1.50,
-- whereas the intent in Q2 is to count a player's return only once so that the ratio is 1/1 for each returning player, i.e. (1 + 1) / 2 = 1.00.
-- (Note: As written, Q2 uses COUNT() without DISTINCT so it actually would sum duplicates as well, but the counterexample illustrates how design differences in the joins can lead developers to get different results.)

