);

counterexample:
INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (1, 'Alice', NULL, 50000);
INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (2, 'Bob', NULL, 60000);

-- For Alice we insert a bonus record that does not meet the condition BONUS < 1000
INSERT INTO BONUS (EMPID, BONUS) VALUES (1, 1500);

-- Bob has no BONUS row, so his LEFT JOIN yields a NULL bonus (which qualifies via BONUS IS NULL)

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES
(1, '2020-01-01', 100, 5);

-- For player 1, insert two records on the day after his first event (simulate duplicate records)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES
(1, '2020-01-02', 101, 10);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES
(1, '2020-01-02', 102, 20);

-- For player 2, only one activity on the first day and one on the next day
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES
(2, '2020-01-05', 200, 8);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES
(2, '2020-01-06', 201, 12);

-- Assume that in our test scenario the PK constraint is relaxed so that a player can have multiple activities in the same day.

-- Player 1 has two activities on its first day (2020-01-01) and one activity on the next day (2020-01-02).
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 101, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 102, 7);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 101, 6);

-- Player 2 logs in only once (so will not have a second activity and will not trigger the consecutive–day logic in either query)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-05', 103, 4);

-- Explanation of outcomes:
-- For player 1, the subquery in Q1 computes MIN(EVENT_DATE) = '2020-01-01'. The join then finds that there is an activity on '2020-01-02' (which equals MIN(EVENT_DATE) + 1) so player 1 is counted in the numerator.
-- In Q2, the window function orders player 1's two rows on 2020-01-01 arbitrarily. One becomes DATE_NUM=1 and the other DATE_NUM=2. For the row with DATE_NUM=2, LAG(DATE_ADD(EVENT_DATE, INTERVAL 1 DAY),1) looks at the other record (with date 2020-01-01) and yields '2020-01-02'. However, the row’s own EVENT_DATE remains '2020-01-01', so the comparison fails. Thus player 1 is not counted in Q2’s numerator.
-- The denominators (distinct player counts) are the same (players 1 and 2). Therefore, Q1 yields a fraction of 1/2 = 0.50 while Q2 yields 0/2 = 0.00, showing the difference.

