-- Create two products
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product 1', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'Product 2', 200);

-- For Product 1, insert two sales: one in the desired range and one out of range
-- (Assume that later an application‐level filter causes the 2019-04-01 sale to be ignored in the join for Q2,
--  even though it is present in the SALES table and so is seen by Q1.)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE)
  VALUES (1, 1, 1, '2019-02-01', 10, 100);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE)
  VALUES (1, 1, 1, '2019-04-01', 5, 100);

-- For Product 2, insert one sale that is in range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE)
  VALUES (2, 2, 2, '2019-02-15', 20, 200);

/*
Explanation of the counterexample:
In the SALES table the raw data for product 1 shows one sale on 2019-02-01 and one on 2019-04-01. Therefore,
if one aggregates over all SALES (as Q1 does in its subquery), product 1 is disqualified because its maximum sale date
is later than 2019-03-31. However, suppose that for the purpose of joining in Q2 there is an additional condition (or view
logic) that filters out the 2019-04-01 sale (for example, because that record was marked inactive or similar). Then the
join in Q2 brings in only the 2019-02-01 sale for product 1 and the GROUP BY computes MIN(SALE_DATE)=MAX(SALE_DATE)='2019-02-01',
thus including product 1. Product 2 is included by both queries. This shows that Q1 and Q2 are not semantically equivalent.
*/

