  (1, '2023-01-01', 'DESKTOP', 10);

INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES
  (1, '2023-01-01', 'MOBILE', 20);

INSERT INTO SPENDING (USER_ID, SPEND_DATE, PLATFORM, AMOUNT) VALUES
  (2, '2023-01-01', 'DESKTOP', 30);

-- Note: User 1, by having spending on both DESKTOP and MOBILE on the same date, aggregates into a single row with computed PLATFORM = 'BOTH'.
-- However, because the union that drives the join emits one row per spend_date for each of the three literal platform values,
-- it is possible (if one is not careful) for User 1's data to appear in duplicate in the joined results. 
-- Q1 (using COUNT(User_ID)) would then over‐count such a user, whereas Q2 (using COUNT(DISTINCT USER_ID)) correctly avoids double counting.

-- For the purpose of this counterexample assume that although EVENT_DATE is of type DATE,
-- the underlying data comes from full timestamps that are truncated to the day, so that two rows for the same player on the same day can occur without conflicting

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 100, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 200, 3);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-02-01', 300, 7);

-- If one runs Q1 against this data, both rows for PLAYER_ID = 1 are returned (because both have the minimum date '2021-01-01').
-- If instead Q2 were implemented with ROW_NUMBER() OVER (PARTITION BY PLAYER_ID ORDER BY EVENT_DATE) as R1 (instead of RANK) and then filtering on R1 = 1,
-- only one of the two rows for PLAYER_ID = 1 would be returned. This behavior difference shows the two queries are not semantically equivalent.

