counterexample:
/*
Assume that while the logical schema indicates a primary key on (PLAYER_ID, EVENT_DATE), the underlying logging system actually allows duplicate sessions on the same day for a given player (eg, because of slight differences in session details not captured here).
This test data inserts two players. Player 1 has two activity rows on the day after install; player 2 has just one retention event. 
*/

-- Player 1, install on 2023-01-01
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 5);
-- Two sessions on the day after install (duplicate retention events)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 100, 3);
