-- Assume the ACTIVITY table already exists as defined.
-- (Note: Although the ACTIVITY table has a primary key on (PLAYER_ID,EVENT_DATE),
--  data issues sometimes lead to duplicate records for the same player and date.)

-- For testing purposes we will insert duplicate records for player 1 on the same day.

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 100, 2);
-- Duplicate record for player 1 on the consecutive day (data anomaly):
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 3);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 200, 1);

-- Now, running Q1 and Q2 on this data will produce different results:
-- Q1 will compute: (2 / 2) = 1.00 because player 1 contributes 2 consecutive–day rows and player 2 contributes 0, over 2 distinct players.
-- Q2 will compute: (1 / 2) = 0.50 because the left join returns at most one match per player.

