-- This order is with the red company but has a NULL SALES_ID. It will be joined in Q2, causing GETSALESID to include a NULL, which then makes 'NOT IN (NULL)' evaluate to false for every row.
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (1, 1, NULL, '2021-01-01', 500);

-- Assuming that for the purposes of testing the application allows duplicate activity records on the same day for a given player (for example, because other fields differentiate them even though the logical key is (PLAYER_ID, EVENT_DATE))

-- Player 1 plays on 2021-01-01 and then has two separate consecutive activities on 2021-01-02
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 1, 10);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 1, 20);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 2, 30);

-- Player 2 plays only once, so has no next-day record
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-05', 1, 15);

-- Expected results:
-- Q1: For player 1, the join finds two rows where (MIN_DATE + 1) equals EVENT_DATE so the sum is 2; for player 2 no such row exists. The fraction is ROUND(2/2,2) = 1.00.
-- Q2: Only the min row for player 1 qualifies and its left join finds a consecutive-day row so player 1 is counted once; player 2 is not counted. The fraction is ROUND(1/2,2) = 0.50.

-- Thus the two queries return different results (1.00 vs. 0.50).

