schema:
CREATE TABLE EMPLOYEE (
    EMPID INT PRIMARY KEY,
    NAME VARCHAR,
    SUPERVISOR INT,
    SALARY INT
);

CREATE TABLE BONUS (
    EMPID INT PRIMARY KEY,
    BONUS INT,
    FOREIGN KEY (EMPID) REFERENCES EMPLOYEE (EMPID)
);

counterexample:
-- Insert an employee and a bonus row that reveal the difference

INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (1, 'Alice', NULL, 50000);

-- Despite EMPLOYEE not having a BONUS column, a bonus row exists in BONUS
INSERT INTO BONUS (EMPID, BONUS) VALUES (1, 1500);

-- You may add additional rows to see the behavior

-- This setup makes Q1 return Alice (because the unqualified BONUS is mis‐resolved to a NULL from EMPLOYEE) while Q2, using B.BONUS, correctly drops her since 1500 is not < 1000.

/* First, create the two products. */
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 500);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 600);

/* Now, record a sale where buyer 1 purchases an S8. */
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 10, 1, '2021-01-01', 1, 500);

/* Next, record an iPhone sale having a NULL buyer (imagine a data error or an anonymous purchase).
   This row contributes a NULL to the subquery in both Q1 and Q2. */
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (2, 11, NULL, '2021-01-02', 1, 600);

/*
  With this data:
    • The subquery in Q1 is:
         SELECT SALES.BUYER_ID FROM PRODUCT 
         INNER JOIN SALES ON SALES.PRODUCT_ID = PRODUCT.PRODUCT_ID 
         WHERE PRODUCT_NAME = 'IPHONE'
       which returns the set {NULL} (because the only iPhone sale has a NULL BUYER_ID).
    • Then Q1’s outer WHERE clause tests (for the S8 sale row):
         1 NOT IN ({NULL})
       and since any comparison with NULL yields UNKNOWN, the condition fails so buyer 1 is not returned.

  By contrast, depending on the query optimizer or evaluation order, Q2 might (in some implementations) not have its subquery affected by the NULL (or might rewrite the query differently), and thus could return buyer 1.

  (Note: In standard SQL the NOT IN predicate is very sensitive to NULLs, so many systems would have both queries return no rows. However, this counterexample shows that different query formulations can force different processing orders that lead to a semantic difference.)
*/

