-- For the purpose of this test, assume that the ACTIVITY table can record multiple sessions per day for a player (e.g. by having an implicit session id or timestamp not shown in the schema).

-- Player 1 installs on 2021-01-01 and has two sessions on 2021-01-02 (the retention day).
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 10, 1);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 10, 5);
