CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR,
    FOLLOWER VARCHAR,
    PRIMARY KEY (FOLLOWEE, FOLLOWER)
);

counterexample:
-- Insert rows into FOLLOW that do not violate the (case‐sensitive) primary key constraint
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('alice', 'Bob');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('alice', 'bob');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'alice');

-- Explanation of the data:
-- • The first two rows mean that 'alice' is followed by 'Bob' and by 'bob'. Since the PK is case‐sensitive these are two different rows.
-- • The third row makes sure that 'alice' appears in the FOLLOWER column (as the follower of 'Bob'). Thus, 'alice' qualifies for the subqueries in both Q1 and Q2.

-- Under a case‐insensitive interpretation of names (or using an application rule that treats 'Bob' and 'bob' as identical),
-- Q1 will count 2 rows for 'alice' (NUM = 2) while Q2 will count only 1 distinct follower (NUM = 1),
-- thereby producing different results.

