counterexample:
-- (Assuming that for testing purposes the PROJECT table is altered to add an extra column named EXPERIENCE_YEARS.)

-- Insert test data into EMPLOYEE
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (1, 'Alice', 5);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (2, 'Bob', 7);

-- Insert test data into PROJECT. Note: the table here is assumed to include the additional EXPERIENCE_YEARS column
-- The foreign key on EMPLOYEE_ID is maintained.
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID, EXPERIENCE_YEARS) VALUES (1, 1, 50);  
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID, EXPERIENCE_YEARS) VALUES (1, 2, 70);

-- When executing Q1, the join uses the explicitly qualified EMPLOYEE.EXPERIENCE_YEARS so the average computed is (5+7)/2 = 6.00
-- However, Q2’s unqualified reference to EXPERIENCE_YEARS will resolve to PROJECT.EXPERIENCE_YEARS and the average computed is (50+70)/2 = 60.00

-- This demonstrates that although the two queries look very similar they can produce different results if an ambiguous column name exists in more than one joined table.

