    PRODUCT_KEY INT PRIMARY KEY
);

ALTER TABLE CUSTOMER
ADD FOREIGN KEY (PRODUCT_KEY)
REFERENCES PRODUCT(PRODUCT_KEY);

counterexample:
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (0);

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 1);

-- Assume that, for testing purposes, we have a relaxed constraint that allows duplicate entries in PRODUCT (or that PRODUCT is actually a view over a join that may produce duplicates).

-- Insert two rows for product_id = 1 (with slightly different names to simulate the problem)
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Widget', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Widget Duplicate', 100);

-- Insert one sales record for product_id = 1, with SALE_DATE within the given range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 100, '2019-02-15', 5, 50);

-- Also add a product that should not qualify: product_id = 2
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'Gadget', 200);

-- And insert two sales for product_id = 2: one in–range and one out–of–range so it does not qualify
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 10, 101, '2019-02-15', 3, 80);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 11, 102, '2019-04-01', 2, 90);

/*
When Q1 runs:
  • The derived table (based solely on SALES) groups product 1 and 2. For product 1 the only sale is '2019-02-15' (which is between 2019-01-01 and 2019-03-31) so product 1 qualifies; product 2 does not qualify because its MAX(SALE_DATE) = '2019-04-01' (outside the period).
  • Joining with PRODUCT then returns two rows for product 1 (one from each duplicate row in PRODUCT).

When Q2 runs:
  • The join between SALES and PRODUCT eliminates product 2 (because one of its sales is out–of–range) and, after grouping by S.PRODUCT_ID the duplicate PRODUCT rows for product 1 collapse. With the DISTINCT the result is a single row for product 1.

Thus, Q1 returns two rows while Q2 returns one row, demonstrating that the two queries are not equivalent.
*/

