/* Note: For the purpose of this counterexample we assume that due to a data error the primary key constraint is not enforced so that duplicate ACTIVITY records for the same (PLAYER_ID, EVENT_DATE) are possible. */

-- Player 1 has two activity records on the day after his first (minimum) event.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 10, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 11, 3);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 12, 4);

-- Player 2 is normal (only one record on his min day, no consecutive event)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-05', 20, 6);

/*
Explanation of results:
For Player 1: The subquery (TEMP) computes MIN(EVENT_DATE) = '2020-01-01' so the expected consecutive-day date is '2020-01-02'.
  • In Q1 the join produces two rows for player 1 but the numerator (SUM CASE...) only adds 1 for player 1 because the aggregation (over TEMP) is intended to count per player. The denominator is COUNT(DISTINCT TEMP.PLAYER_ID) = 2.
  • In Q2 the join produces the same two rows for player 1, and if one is not careful the duplicated consecutive‐day events will add up in the SUM(CASE...) (giving 2 for player 1), while the DISTINCT in the denominator still gives 2.
Thus the final fraction differs between Q1 and Q2 (for example, 1/2 = 0.50 versus 2/2 = 1.00) when extra duplicate rows occur.
*/

