counterexample:
-- The following INSERT statements assume that (for testing purposes only) the PRIMARY KEY constraint on PRODUCT is turned off or not enforced.

-- Insert duplicate rows into PRODUCT (violating the ideal constraint but useful for a counterexample)
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

-- Insert CUSTOMER rows. (Assume the CUSTOMER table is allowed to have multiple purchases per customer even if CUSTOMER_ID is ideally unique.)
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 2);

-- Explanation:
-- In Q1: for customer 100, COUNT(DISTINCT PRODUCT_KEY) = 2, and (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT) = 2, so customer 100 qualifies.
-- In Q2: for customer 100, the count from the deduplicated CTE is 2, but (SELECT COUNT(*) FROM PRODUCT) = 3, so 100 does not qualify.

