-- Valid sale for product 1 within the allowed date range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 10, 100, '2019-02-15', 5, 50);

-- A sale with PRODUCT_ID as NULL and a sale date outside the permitted range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (NULL, 20, 200, '2018-12-31', 3, 30);

/*
  Assume that due to a data‐loading error the PRODUCT table ends up with two rows having the same PRODUCT_ID (even though a PK is intended).
  The following INSERTs (executed in an environment where the duplicate is not prevented) illustrate the counterexample.
*/

-- Insert (duplicate) product rows
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product A', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Product A (duplicate)', 100);

-- Insert sales rows for PRODUCT_ID = 1, one in the allowed quarter and one outside
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (1, 10, 100, '2019-02-15', 5, 50);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
  VALUES (1, 10, 100, '2019-04-01', 3, 50);

/*
  In this test database:
  • Q1’s subquery groups over SALES for product 1 and finds MIN(sale_date) = '2019-02-15' and MAX(sale_date) = '2019-04-01' – because of the out–of–range sale the HAVING clause fails, so Q1 returns no row for product 1.
  • Q2, however, first joins SALES with PRODUCT. Because the product row appears twice it may happen (in some SQL engines that perform the join before grouping) that only the in–range sale is retained in one branch of the join, so that the GROUP BY ends up with both MIN and MAX equal to '2019-02-15' and the product is (incorrectly) returned.

  This demonstrates that if the data (or the ETL that loads it) is not perfectly clean, the two queries can yield different results.
*/

