schema:
CREATE TABLE CUSTOMER (
    ID INT PRIMARY KEY,
    NAME VARCHAR,
    REFEREE_ID INT,
    FOREIGN KEY (REFEREE_ID) REFERENCES CUSTOMER(ID)
);

counterexample:
-- First, create a valid customer with ID = 0 (so that 0 is a legitimate referee value)
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (0, 'DefaultReferee', NULL);

-- Insert a customer whose REFEREE_ID is NULL
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (1, 'Alice', NULL);

-- Insert a customer whose REFEREE_ID is not 2 (for example, 0, which now is valid because a customer with ID 0 exists)
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (2, 'Bob', 0);

-- Insert a customer with REFEREE_ID = 2 (this row should be filtered out by both queries)
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (3, 'Carol', 2);

-- Now, consider joining the results of each query on the referee details. For Q2 the row for 'Alice' will have its REFEREE_ID coalesced to 0 and join with 'DefaultReferee', while Q1 will leave the NULL as NULL and not join. (The following JOIN queries demonstrate the semantic difference in a larger context.)

-- Q1 join example (using a LEFT JOIN that does not match on NULL):
SELECT C.NAME AS Customer, R.NAME AS Referee
FROM CUSTOMER C
LEFT JOIN CUSTOMER R ON C.REFEREE_ID = R.ID
WHERE C.REFEREE_ID <> 2 OR C.REFEREE_ID IS NULL;

-- Q2 join example (since COALESCE(C.REFEREE_ID,0) returns 0 for Alice, it will join with DefaultReferee):
SELECT C.NAME AS Customer, R.NAME AS Referee
FROM CUSTOMER C
LEFT JOIN CUSTOMER R ON COALESCE(C.REFEREE_ID,0) = R.ID
WHERE COALESCE(C.REFEREE_ID,0) != 2;

-- In the Q2 join example, 'Alice' (ID=1) will appear with 'DefaultReferee' as its referee, whereas in Q1 the NULL remains unmatched.

