CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID)
);

CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT PRIMARY KEY,
    NAME VARCHAR,
    EXPERIENCE_YEARS INT
);

CREATE INDEX idx_PROJECT_EMPLOYEE_ID ON PROJECT (EMPLOYEE_ID);

ALTER TABLE PROJECT
ADD FOREIGN KEY (EMPLOYEE_ID)
REFERENCES EMPLOYEE (EMPLOYEE_ID);

counterexample:
/* First, extend the EMPLOYEE table with a PROJECT_ID column. This does not break any foreign key constraints since it is not used there. */
ALTER TABLE EMPLOYEE ADD COLUMN PROJECT_ID INT;

/* Insert employees. Note that the EMPLOYEE.PROJECT_ID values are deliberately chosen to differ from the PROJECT.PROJECT_ID used below. */
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS, PROJECT_ID) VALUES (1, 'Alice', 10, 999);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS, PROJECT_ID) VALUES (2, 'Bob', 20, 1);

/* Insert PROJECT rows. Both rows refer to project 1 (the only valid PROJECT.PROJECT_ID) but to different employees. */
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (1, 1);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (1, 2);

/*
  Under Q1, the query reads:
    SELECT A.PROJECT_ID, ROUND(AVG(B.EXPERIENCE_YEARS), 2) AS AVERAGE_YEARS
    FROM PROJECT AS A INNER JOIN EMPLOYEE AS B ON A.EMPLOYEE_ID = B.EMPLOYEE_ID
    GROUP BY A.PROJECT_ID
  Because A.PROJECT_ID is always 1, the result will be one row: (1, 15.00).

  Under Q2, the query reads:
    SELECT PROJECT_ID, ROUND(AVG(EXPERIENCE_YEARS),2) AS AVERAGE_YEARS
    FROM PROJECT INNER JOIN EMPLOYEE ON PROJECT.EMPLOYEE_ID = EMPLOYEE.EMPLOYEE_ID
    GROUP BY PROJECT_ID
  If the DBMS, when faced with the ambiguous unqualified PROJECT_ID, ends up resolving it to EMPLOYEE.PROJECT_ID (because EMPLOYEE now has a PROJECT_ID column), then the two joined rows will fall into different groups: one group for 999 (from employee 1) and one group for 1 (from employee 2). The results would be:
    (999, 10.00) and (1, 20.00)
  which is different from Q1’s single row (1, 15.00).
*/

