-- Sale of S8 by buyer 1
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 10, 1, '2023-10-01', 1, 1000);

-- Sale of IPHONE with a NULL buyer_id
