VALUES (2, 20, NULL, '2023-10-02', 1, 1200);

-- Assume the ACTIVITY table already exists with the given schema.
-- Note: Although the schema defines PRIMARY KEY (PLAYER_ID, EVENT_DATE), we are simulating a situation where duplicate records for the same player and same date occur (for example, because activities arriving from different devices were not deduplicated properly).

-- Player 1: a normal player with one row for signup and one consecutive day record
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 100, 10);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 100, 20);

-- Player 2: a player with the correct signup but with TWO records on the day following signup
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-01', 200, 15);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-02', 200, 25);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-02', 201, 30);

-- When running Q1 and Q2 on this test data:
-- Q1 will sum over the join and count 1 for player 1 and 2 for player 2, with denominator 2 (players), yielding 3/2 = 1.50,
-- whereas Q2 will count only distinct players with a qualifying first-pair, yielding 2/2 = 1.00.
-- This demonstrates that Q1 and Q2 are not semantically equivalent.

