INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 11, 3);

-- Player 2 logs in on 2020-01-01
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-01', 20, 4);

-- Now, to simulate multiple distinct activity records on the same calendar day (2020-01-02) without violating the schema’s uniqueness constraints, one common approach is to assume that the underlying system actually records a timestamp (even if EVENT_DATE is a DATE, the additional detail distinguishes separate events internally). Here we simulate this by inserting two rows for player 2 on 2020-01-02 using different DEVICE_ID (or GAMES_PLAYED) values, assuming that in the real data they would be considered distinct events.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-02', 21, 2);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-02', 22, 6);

/* Insert the products */
