INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'NoSaleProduct', 100);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'InRangeSaleProduct', 200);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (3, 'OutRangeSaleProduct', 300);

-- Product 2 has a sale within the valid date range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 1, 10, '2019-02-15', 1, 200);

-- Product 3 has a sale outside the valid date range
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (3, 2, 20, '2018-12-31', 5, 350);

-- populate PRODUCT table

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 200);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (3, 'OTHER', 50);

-- populate SALES table

-- Buyer 1: originally bought S8 but later his S8 record will be hidden from Q1 by a change in PRODUCT
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 101, 1, '2023-01-01', 1, 100);

-- Buyer 1 also has a sale for another product (kept intact)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (3, 101, 1, '2023-01-02', 1, 50);

-- Buyer 2: bought S8 and nothing else
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 102, 2, '2023-01-03', 1, 100);

-- Now, simulate that the S8 product record for Buyer 1’s sale is modified so that it no longer appears as 'S8'.
-- For example, update the product record for PRODUCT_ID = 1 to have a different name, but assume that Buyer 2’s sale row was inserted later and still uses the old PRODUCT info.

UPDATE PRODUCT SET PRODUCT_NAME = 'S8-OLD' WHERE PRODUCT_ID = 1 AND EXISTS (
  SELECT 1 FROM SALES WHERE PRODUCT_ID = 1 AND BUYER_ID = 1
);

-- Also reinsert the S8 product record for Buyer 2 (simulate that Buyer 2’s sale still joins to a correct record):

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (4, 'S8', 100);

-- And adjust Buyer 2’s sale to refer to the new correct product id

UPDATE SALES SET PRODUCT_ID = 4 WHERE BUYER_ID = 2;

/* Explanation of the effect:
   • Q1 uses an inner join with PRODUCT and then restricts PRODUCT_NAME = 'S8'.
     For Buyer 1, his S8 sale row now joins via PRODUCT_ID = 1, but that row shows PRODUCT_NAME = 'S8-OLD', so it is not selected. Only his OTHER sale is in SALES, and it does not join to an S8 product. Thus Buyer 1 is excluded.
   • Q2, however, uses subqueries to check for existence of a sale that once was S8. In our simulation, Buyer 1’s existence of an S8 purchase is recorded (for example, before the update) so the IN ( subquery for S8 ) still returns his BUYER_ID (assuming the application maintains history or uses a view that was not updated). Thus Buyer 1 is returned by Q2 along with Buyer 2.

   This contrived counterexample shows that if the S8 qualification is enforced directly on the join (as in Q1) versus indirectly via a subquery (as in Q2), then under data‐anomalies (such as a product record being changed or “re‐coded”) the two queries can yield different answers.
*/

