CREATE TABLE VIEWS (
    ARTICLE_ID INT,
    AUTHOR_ID INT,
    VIEWER_ID INT,
    VIEW_DATE DATE
);

counterexample:
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES
  (1, 'Product A', 100);

-- A sale for Product A that lies within the quarter (2019 Q1)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES
  (1, 10, 20, '2019-02-15', 5, 500);

-- A spurious sale row with a NULL PRODUCT_ID and a sale date outside the quarter
-- (This row will be grouped separately in Q1, so it does not affect the aggregation for Product A,
--  but it will appear in the NOT IN subquery in Q2, returning a NULL and thus nullifying the condition.)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES
  (NULL, 11, 21, '2019-04-01', 3, 300);

schema:
CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID)
);

CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT PRIMARY KEY,
    NAME VARCHAR,
    EXPERIENCE_YEARS INT
);

CREATE INDEX idx_PROJECT_EMPLOYEE_ID ON PROJECT (EMPLOYEE_ID);

ALTER TABLE PROJECT
ADD FOREIGN KEY (EMPLOYEE_ID)
REFERENCES EMPLOYEE (EMPLOYEE_ID);

